import{_ as l,C as r,c as s,o as u,ag as o,j as e,G as a,a as n}from"./chunks/framework.Bw-5EFTY.js";const w=JSON.parse('{"title":"FluentCRM Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/fluentcrm-integration-with-fluenaffiliate.md","filePath":"guide/integrations/fluentcrm-integration-with-fluenaffiliate.md","lastUpdated":1751451761000}'),g={name:"guide/integrations/fluentcrm-integration-with-fluenaffiliate.md"};function f(c,t,d,p,m,h){const i=r("ZoomableImage");return u(),s("div",null,[t[0]||(t[0]=o('<h1 id="fluentcrm-integration-with-fluentaffiliate" tabindex="-1">FluentCRM Integration with FluentAffiliate <a class="header-anchor" href="#fluentcrm-integration-with-fluentaffiliate" aria-label="Permalink to &quot;FluentCRM Integration with FluentAffiliate&quot;">​</a></h1><p>FluentCRM is a powerful email marketing automation plugin for WordPress. With FluentAffiliate, you can manage your email marketing campaigns and affiliate commissions seamlessly.</p><p>In this guide, we&#39;ll walk you through how to connect FluentCRM with FluentAffiliate step by step.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Make sure both the FluentCRM and FluentAffiliate plugins are installed and activated on your website.</p></div><h2 id="enable-fluentcrm-in-fluentaffiliate" tabindex="-1">Enable FluentCRM in FluentAffiliate <a class="header-anchor" href="#enable-fluentcrm-in-fluentaffiliate" aria-label="Permalink to &quot;Enable FluentCRM in FluentAffiliate&quot;">​</a></h2><p>First, let&#39;s enable the integration to get the two plugins working together.</p><ol><li>Once FluentCRM is active, go to the <strong>FluentAffiliate Dashboard</strong>.</li><li>From the top menu, click on <strong>Settings</strong>, and from the left sidebar, select the <strong>Integration Settings</strong> option.</li><li>You will see a list of available integrations. Find <strong>FluentCRM</strong> in this list and click the <strong>toggle</strong> button next to it to turn it on.</li></ol><p>Your <strong>FluentCRM</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing you to automate affiliate-related email marketing tasks.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how the integration works.</p>',9)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/fluentcrm-integration-settings.webp",alt:"Integration Settings"})]),t[1]||(t[1]=o('<h2 id="configure-fluentcrm-settings" tabindex="-1">Configure FluentCRM Settings <a class="header-anchor" href="#configure-fluentcrm-settings" aria-label="Permalink to &quot;Configure FluentCRM Settings&quot;">​</a></h2><p>After enabling the integration, a pop-up will appear where you can configure the <strong>settings</strong>.</p><ol><li>Check the box for <strong>Add Affiliates to FluentCRM Contact List</strong>.</li><li>In the box that appears, search for and select the specific contact list where you want your new affiliates to be added.</li><li>After selecting the options, simply click the <strong>Save Settings</strong> button to save your settings.</li></ol>',3)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/fluentcrm-settings-configuration.webp",alt:"FluentCRM Settings"})]),t[2]||(t[2]=o('<h2 id="set-up-automation" tabindex="-1">Set Up Automation <a class="header-anchor" href="#set-up-automation" aria-label="Permalink to &quot;Set Up Automation&quot;">​</a></h2><p>After configuring the basic settings, you can set up automated workflows to manage your affiliate communications.</p><p>FluentCRM provides <strong>Triggers</strong> specifically designed for FluentAffiliate to run automations.</p><p>To get all the <strong>Triggers</strong>, go to the <strong>Automations</strong> section from the FluentCRM navbar and click the <strong>+ New Automation</strong> button.</p><p>To learn the detailed process of creating a new automation funnel, read this <a href="https://fluentcrm.com/docs/introduction-to-fluentcrm-automation/" target="_blank" rel="noreferrer">Documentation</a>.</p>',5)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/automation-setup.webp",alt:"New Automation"})]),t[3]||(t[3]=e("p",null,[n("Now, a pop-up page will appear with all the "),e("strong",null,"Popular pre-built funnel templates"),n(" for creating automation, where the full funnel diagram will be ready automatically.")],-1)),t[4]||(t[4]=e("p",null,[n("If you want to create your automation funnel from scratch, simply click on the "),e("strong",null,"Create from Scratch"),n(" tab (e.g., here, I have created a new automation from scratch).")],-1)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/prebuilt-templates.webp",alt:"Pre-built Templates"})]),t[5]||(t[5]=o('<h2 id="triggers-for-fluentaffiliate" tabindex="-1">Triggers for FluentAffiliate <a class="header-anchor" href="#triggers-for-fluentaffiliate" aria-label="Permalink to &quot;Triggers for FluentAffiliate&quot;">​</a></h2><p>Go to <strong>FluentAffiliate</strong> from the left sidebar, and all the Triggers for FluentAffiliate will appear.</p><p>Now, choose your desired trigger. Here, you can give a <strong>Title</strong> to your Automation in the <strong>Internal Label</strong> field for easy referencing later. But if you leave it blank, the title will be automatically set based on your chosen trigger. All the triggers are:</p><ul><li><p><strong>New Affiliate Created:</strong> If you select this trigger, the automation will start when a new affiliate is created in FluentAffiliate.</p></li><li><p><strong>New referral created:</strong> If you select this trigger, the automation will start when a new referral is created in FluentAffiliate.</p></li><li><p><strong>New Payout Created:</strong> If you select this trigger, this will start when a new payout is created in FluentAffiliate. Create targeted campaigns for your affiliates.</p></li></ul>',4)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/fluentaffiliate-trigger.webp",alt:"FluentAffiliate Trigger"})]),t[6]||(t[6]=e("h2",{id:"run-email-campaigns",tabindex:"-1"},[n("Run Email Campaigns "),e("a",{class:"header-anchor",href:"#run-email-campaigns","aria-label":'Permalink to "Run Email Campaigns"'},"​")],-1)),t[7]||(t[7]=e("p",null,"FluentCRM allows you to run Email campaigns, particularly for FluentAffiliate contacts.",-1)),t[8]||(t[8]=e("p",null,[n("First, go to "),e("strong",null,"All Campaigns"),n(" under the Emails section from the FluentCRM navbar, and click the "),e("strong",null,"+ Create New Campaign"),n(" button.")],-1)),t[9]||(t[9]=e("p",null,[n("To learn the detailed process of creating a new Email Campaign, read this "),e("a",{href:"https://fluentcrm.com/docs/setting-up-campaign/#create-a-new-campaign",target:"_blank",rel:"noreferrer"},"Documentation"),n(".")],-1)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/create-campaigns.webp",alt:"Advanced Filters"})]),t[10]||(t[10]=o('<h2 id="by-advanced-filter" tabindex="-1">By Advanced Filter <a class="header-anchor" href="#by-advanced-filter" aria-label="Permalink to &quot;By Advanced Filter&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>To use this advanced filter to select the email campaign recipients, you need to have the <a href="https://fluentcrm.com/docs/how-to-install-upgrade-and-activate-license/" target="_blank" rel="noreferrer">FluentCRM Pro Plugin</a> installed and activated on your WordPress Site.</p></div><p>First, you need to contact FluentAffiliate manually or use automation to run an email campaign with an advanced filter. Select By Advanced Filter option and then choose the custom contact condition.</p><p>Now, click on the <strong>+Add</strong> button to start the filtering, where you will get many options to set the conditions. Here you will find the FluentAffiliate option, and click on it.</p><p>You can add more filters by clicking the <strong>+Add</strong> button, add filters against the existing filter by clicking the <strong>+ OR</strong> button, and delete any existing filter by clicking the <strong>Trash</strong> Icon.</p>',5)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/advanced-filter-settings.webp",alt:"Advanced Filters"})]),t[11]||(t[11]=o('<h3 id="contact-management" tabindex="-1">Contact Management <a class="header-anchor" href="#contact-management" aria-label="Permalink to &quot;Contact Management&quot;">​</a></h3><p>If you want to filter out your FluentAffiliate contacts, go to the FluentCRM <strong>Contact</strong> section. Click the <strong>toggle</strong> button to enable the <strong>Advanced Filter</strong>.</p><p>Next, click the <strong>+Add</strong> icon and select the FluentAffiliate option. Here you will find a filter condition. After that, set the condition filter and click the <strong>Filter</strong> button.</p>',3)),e("p",null,[a(i,{src:"/guide/public/images/integrations/fluentcrm/contact-filtering-options.webp",alt:"Contact Filtering"})]),t[12]||(t[12]=o('<h3 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h3><p>Here are solutions to common issues you might encounter:</p><ul><li><strong>Integration Toggle Not Visible:</strong> Ensure both FluentCRM and FluentAffiliate are activated. If the issue continues, deactivate and reactivate both plugins, and then check again.</li><li><strong>Contact Sync Not Working:</strong> Verify that the contact sync option is enabled and that your FluentCRM settings are properly configured.</li><li><strong>Automation Not Triggering:</strong> Check if the triggers are properly set up and that the conditions are being met.</li></ul><p>And that&#39;s it. This is an easy process to integrate FluentCRM with FluentAffiliate.</p>',4))])}const _=l(g,[["render",f]]);export{w as __pageData,_ as default};
